'use strict';
const $=id=>document.getElementById(id),C=TransportCore;
let state={schemaVersion:1,events:[],candidates:[],workplaces:[{id:'shibuya',name:'渋谷スタジオ（架空）',aliases:['渋谷','架空区桜通1-2']},{id:'makuhari',name:'幕張イベント会場（架空）',aliases:['幕張','架空展示場']}],routes:[],travelRecords:[],outputSettings:{format:null}},source='';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sample='タイトル,開始日,終了日,終日,場所,説明\r\n配信仕込み,2026-10-05,2026-10-05,FALSE,架空区桜通1-2,電車か社用車か未確認\r\n秋イベント,2026-10-10,2026-10-12,TRUE,架空展示場,宿泊と自宅発が混在。各日の移動を確認\r\n打合せ,2026-10-14,2026-10-14,FALSE,,渋谷スタジオ集合\r\n私用の買物,2026-10-15,2026-10-15,FALSE,,\r\n配信@都内,2026-10-17,2026-10-17,FALSE,,詳細未定\r\n会場間の打合せ,2026-10-18,2026-10-18,FALSE,渋谷,翌日の幕張について相談';
function msg(s){$('message').textContent=s;}
function download(name,data,type){let u=URL.createObjectURL(new Blob([data],{type}));let a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function load(text,name){let events=/\.ics$/i.test(name)?C.parseICS(text):C.parseCSV(text);let rows=C.expand(events,state.workplaces);state.events=events;state.candidates=rows;source=name;render();msg(`${events.length}件の予定から${rows.length}件の日別候補を作成しました。すべて確認待ちです。`);}
function render(){let rows=state.candidates;$('total').textContent=rows.length;for(let k of ['pending','confirmed'])$(k).textContent=rows.filter(r=>r.status===k).length;$('source').textContent=source||'まだデータを読み込んでいません';let visible=rows.filter(r=>$('filter').value==='all'||r.status===$('filter').value);
$('list').innerHTML=visible.length?visible.map(r=>{let index=rows.indexOf(r);return `<article class="card ${esc(r.status)}"><div><div class="day">${esc(r.date)}</div><div class="badge">${{pending:'確認待ち',confirmed:'勤務確認済み',excluded:'対象外'}[r.status]}</div><p>${r.event.allDay?'終日':esc(r.event.startTime||'時刻未指定')}</p></div><div><div class="title">${esc(r.event.title||'（タイトルなし）')}</div><div class="detail">場所：${esc(r.event.location||'記載なし')}<br>説明：${esc(r.event.description||'記載なし')}</div><div class="reasons">${esc(r.reason)}${r.matches.map(m=>'<p>候補：'+esc(m.name)+'<br>'+esc(m.reasons.join(' / '))+'</p>').join('')}</div><p class="sub">移動実績：未記録 ／ 精算金額：未確認</p></div><div class="edit"><label>勤務地<select data-i="${index}" data-field="siteId"><option value="">未確認・未選択</option>${state.workplaces.map(m=>`<option value="${esc(m.id)}" ${r.siteId===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label><label>勤務の確認<select data-i="${index}" data-field="status">${[['pending','確認待ち'],['confirmed','勤務確認済み'],['excluded','対象外（私用・通常勤務など）']].map(([v,t])=>`<option value="${v}" ${r.status===v?'selected':''}>${t}</option>`).join('')}</select></label><label>確認メモ<input data-i="${index}" data-field="note" value="${esc(r.note)}" placeholder="例：宿泊。帰路は12日のみ"></label></div></article>`;}).join(''):'<div class="empty">表示する候補がありません。ファイル読込またはサンプルから始めてください。</div>';}
$('list').addEventListener('change',e=>{let {i,field}=e.target.dataset;if(i===undefined)return;state.candidates[+i][field]=e.target.value;if(field!=='note')render();});
$('file').onchange=async e=>{try{let f=e.target.files[0];if(!f)return;if(f.size>5e6)throw Error('5MB以下のファイルを選んでください');let text=await f.text();if(text.includes('\ufffd'))throw Error('文字コードをUTF-8で保存してから読み込んでください');if(state.candidates.length&&!confirm('現在の候補と確認結果を置き換えます。必要なら先に作業を保存してください。'))return;load(text,f.name);}catch(err){msg('読み込めませんでした：'+err.message);}finally{e.target.value='';}};
$('sample').onclick=()=>{if(state.candidates.length&&!confirm('現在の候補をサンプルに置き換えますか？'))return;load(sample,'サンプル.csv');};
$('template').onclick=()=>download('ダミー予定.csv','\uFEFF'+sample,'text/csv;charset=utf-8');
$('filter').onchange=render;
$('backup').onclick=()=>download('みちしるべ作業.json',JSON.stringify({...state,source},null,2),'application/json');
$('restore').onchange=async e=>{try{let f=e.target.files[0];if(!f)return;if(f.size>5e6)throw Error('5MB以下の作業ファイルを選んでください');let v=JSON.parse(await f.text());if(v.schemaVersion!==1||!Array.isArray(v.events)||!Array.isArray(v.workplaces)||!Array.isArray(v.candidates))throw Error('作業ファイルの形式が違います');let reconstructed=C.expand(v.events,v.workplaces);let saved=new Map(v.candidates.map(r=>[r.id,r]));for(let r of reconstructed){let old=saved.get(r.id);if(old){r.status=['pending','confirmed','excluded'].includes(old.status)?old.status:'pending';r.siteId=v.workplaces.some(m=>m.id===old.siteId)?old.siteId:'';r.note=String(old.note||'');}}if(state.candidates.length&&!confirm('現在の作業を復元ファイルで置き換えますか？'))return;state={...state,events:v.events,workplaces:v.workplaces,candidates:reconstructed,routes:v.routes||[],travelRecords:v.travelRecords||[],outputSettings:v.outputSettings||{format:null}};source=String(v.source||f.name);masters();render();msg('作業を復元しました');}catch(err){msg('復元できませんでした：'+err.message);}finally{e.target.value='';}};
function cell(s){s=String(s??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
$('export').onclick=()=>{if(!state.candidates.length){msg('先に予定を読み込んでください');return;}let rows=[['日付','予定タイトル','場所','説明','勤務地候補','選択勤務地','確認状態','メモ','精算金額'],...state.candidates.map(r=>[r.date,r.event.title,r.event.location,r.event.description,r.matches.map(m=>m.name).join(' / '),state.workplaces.find(m=>m.id===r.siteId)?.name||'',{pending:'確認待ち',confirmed:'勤務確認済み',excluded:'対象外'}[r.status],r.note,'未確認'])];download('勤務候補一覧.csv','\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');};
let draft=[];function masters(){draft=structuredClone(state.workplaces);drawMaster();}function drawMaster(){$('masters').innerHTML=draft.map((m,i)=>`<div class="masterrow"><input aria-label="勤務地名" data-m="${i}" data-k="name" value="${esc(m.name)}" placeholder="勤務地名"><input aria-label="別名と住所" data-m="${i}" data-k="aliases" value="${esc(m.aliases.join('|'))}" placeholder="別名|住所"><button data-remove="${i}">削除</button></div>`).join('');}
$('masters').oninput=e=>{let {m,k}=e.target.dataset;if(m!==undefined)draft[m][k]=k==='aliases'?e.target.value.split('|').map(x=>x.trim()).filter(Boolean):e.target.value;};
$('masters').onclick=e=>{if(e.target.dataset.remove!==undefined){draft.splice(+e.target.dataset.remove,1);drawMaster();}};
$('add').onclick=()=>{draft.push({id:crypto.randomUUID(),name:'',aliases:[]});drawMaster();};
$('rematch').onclick=()=>{if(draft.some(m=>!m.name.trim())){msg('勤務地名を入力してください');return;}if(state.candidates.length&&!confirm('マスターを保存し、すべての候補を確認待ちに戻して再照合しますか？'))return;try{let rows=C.expand(state.events,draft);state.workplaces=structuredClone(draft);state.candidates=rows;render();msg('勤務地マスターを保存しました');document.querySelector('[data-tab="work"]').click();}catch(e){msg(e.message);}};
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));for(let id of ['work','master','design'])$(id).hidden=id!==b.dataset.tab;});masters();render();
